return {rwnpc01={id="rwnpc01",baseId="rwnpc05",combatid={1,100045},name="村长",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL村长：那画皮出现，这林中的雾气愈浓，其中毒气也愈烈，即使燃火也无法将其轻易驱散。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN他拿出一颗药丸，自己吃下一颗，又将一颗递给你。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：少侠是否也察觉到周身的气力正逐渐消散，眼前之景变得模糊，仿佛置身于梦中？这正是那画皮的妖雾之毒，只需服下这解毒丸即会无事。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN你只觉着整个世界都在摇晃，眼前景象犹如蒙上了一层薄纱，周身的力气如同被无形的枷锁束缚着，难以施展。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：少侠，那画皮妖行踪诡秘，不知何时便会悄然而至，其毒雾更是防不胜防。你我此刻身处险境，莫要再犹豫了，快将解毒丸服下，恢复清明才是。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN令人不安的是，村长的声音似从天边飘来，模糊不清，却有细碎的低语在你耳边回荡，令人心神不宁。你恍惚间只听清：吃下药丸，就可以永远留在此处了。NOR"}},{type="addobject",args={"rwwp07_03"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL村长：少侠，情况危急，莫要犹豫了。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL村长：少侠，莫要被画皮妖的诡计所动摇，它不过是利用幻术，试图离间你我。少侠，莫再迟疑，速将解毒丸服下，我们一齐将此妖拿下。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL村长：可恶，敬酒不吃，吃罚酒！你以为你不吃，我就没有办法了吗？你以为她为何只敢在洞口徘徊？我先解决了你，再解决她！NOR"}},{type="challenge",args={"rwnpc01"}}},caozuoName5="击杀",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="challenge",args={"rwnpc01"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"313002",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"313002",2}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="showbutton",args={5,1}}},autoCondition3={relation="and",conditions={{type="challengewin",args={"rwnpc01"}}}},autoResult3={{type="gaintab",args={"313002",3}},{type="doc",args={[[CYN你武艺高强，尽管毒素缠身，依然招招犀利，步步紧逼，将他斩于剑下。NOR
CYN但你看见，一道虚影闪到了祭坛之下，你直觉告知你，他还未死。NOR]]}},{type="outobject",args={"rwnpc01"}},{type="refresh",args={}}},autoCondition4={relation="and",conditions={{type="challengelose",args={"rwnpc01"}}}},autoResult4={{type="gaintab",args={"313002",3}},{type="doc",args={[[CYN你毒素未清，落于下风，然那画皮妖忽然一晃扑向村长。红色的衣裙包裹住村长，只闻一声凄厉惨叫，村长竟似溶于衣裙之中，叫红色的衣裙愈发鲜红。NOR
CYN然而，你隐约看见，一道虚影闪到了祭坛之下。NOR]]}},{type="outobject",args={"rwnpc01"}},{type="refresh",args={}}},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc02={id="rwnpc02",baseId="rwnpc36",combatid={1,100044},name="画皮",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL画皮：嘻嘻嘻，你吃呀，你吃呀，你吃下后，你就不是你，他就成了你！NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL画皮：嘻嘻嘻，老东西这么着急，身体撑不住了吧？NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="redoc",args={"YEL画皮：哈哈哈哈哈……真是活该！罪有应得！。NOR",[[CYN忽然她又冷静了下来。NOR
YEL画皮：他们这样还死不了，只是失去了躯体，有一日还是会卷土重来的。NOR]],"YEL画皮：哈哈哈哈哈……那些人，被他们夺了躯体，早就救不了了，我不杀他们，他们照样会死，我有什么错？只是尽早为他们解脱罢了！NOR","YEL画皮：不完全铲除他们，他们还会再出来，还会为祸人间！NOR"}},{type="showbutton",args={4,1}},{type="showbutton",args={5,1}}},caozuoName4="降伏",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"313002",4}},{type="doc",args={"CYN你举剑向她刺去，她未曾反抗，伏诛在你的剑下。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN最后一息，她忽然扑向祭坛。随后祭坛燃起蓝色的大火，火中发出许多人撕心裂肺的嘶吼。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="transfer",args={"hdroom1397"}}},caozuoName5="放过",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"313002",4}},{type="doc",args={"CYN她大笑着，你却感受不到她的快乐，只余一身悲戚。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN她慢慢走向祭坛，随后祭坛燃起蓝色的大火，火中发出撕心裂肺的嘶吼，连着她一起淹没在火海。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="transfer",args={"hdroom1397"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"313002",2}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"313002",3}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc03={id="rwnpc03",baseId="rwnpc03",combatid={1,1001},name="南明",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="redoc",args={"YEL南明：嘿呀，我就知道少侠能逃出来的。NOR","YEL南明：我可不是偷跑了，我忙着呢，我可放了好些无辜人呢。当然，也小小的收了些报酬。NOR","YEL南明：这画皮杀了人，即使不死也入不了轮回，这样的结果说不定就是最好的呢。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}}}0000000